import Foundation

enum HiddenCardCatalog {
    static let definitions: [CollectibleDefinition] = [
        CollectibleDefinition(id: "hidden.health.first", name: "律动之心", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "让小小的行动，成为可以接续的节律。", details: "一枚心核在静海上醒来，微弱的搏动只能托起几粒星沙。守潮人每天经过，都会替它清开一道水路，让脉络能舒展一点。\n\n许多次安稳的起落之后，细丝接成了宽阔的支撑。远行者在这里停泊，听见它一下一下地回应潮汐，也重新找到了自己的步调。", hiddenRuleID: "hidden.health.first", series: "健康｜生命与恢复"),
        CollectibleDefinition(id: "hidden.health.streak.7", name: "舒息双翼", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "给投入与恢复，都留出合适的空间。", details: "风谷里的双翼总想把每阵风都抱进怀里，渐渐沉得无法展开。织风人陪它练习一次收拢、一次舒展，让风从叶层之间慢慢经过。\n\n它的纹路逐日变得柔韧。后来，穿谷的人会在翼下歇脚，等纷乱的风平缓下来，再带着自己的节奏走向山口。", hiddenRuleID: "hidden.health.streak.7", series: "健康｜生命与恢复"),
        CollectibleDefinition(id: "hidden.health.streak.14", name: "修复之泉", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "给需要照料的地方，持续而温柔的回应。", details: "古桥下的泉眼曾试着用一次奔涌接好所有裂缝，水却很快散尽。护泉人于是每天清理一处堵塞，让细流沿着能够承接的石纹，逐寸汇拢。\n\n泉水渐渐有了稳定的路径，断开的水渠也重新连起两岸。旅人取水时，会留意脚下细小的缺口，再添上一块合适的石头。", hiddenRuleID: "hidden.health.streak.14", series: "健康｜生命与恢复"),
        CollectibleDefinition(id: "hidden.health.streak.21", name: "眠月之茧", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "允许安静的时日，也成为成长的一部分。", details: "小小的月茧挂在夜树上，听见远处赶路的声音，便急着松开还未长好的外壳。守夜者替它挡住冷风，让它安心留在柔软的月弧里。\n\n星光在茧心慢慢重排。待新的纹路连成，月茧轻轻舒展，为树下疲倦的来客留下一片宁静，让他们睡醒以后再继续旅程。", hiddenRuleID: "hidden.health.streak.21", series: "健康｜生命与恢复"),
        CollectibleDefinition(id: "hidden.health.streak.28", name: "韧生之脊", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "从能够承受的分量开始，慢慢建立支撑。", details: "散落的节段想立刻托起一整座云台，刚刚靠近便被重量冲开。石匠先替它们接好最下方的一节，再让每个接口适应自己的分量。\n\n经过许多次细致的连接，主轴终于能够稳稳立起。后来，云台在上方展开新的空间，每一层都记得检查支点，让成长拥有可靠的依托。", hiddenRuleID: "hidden.health.streak.28", series: "健康｜生命与恢复"),
        CollectibleDefinition(id: "hidden.health.streak.35", name: "步行之轮", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "找到合适的落点，让行动接成自己的路。", details: "两枚足环生来大小不同，总因为想同时落地而跌倒。巡路人陪它们沿软沙慢走，观察哪一刻抬起，哪一刻能把重量安稳交给另一边。\n\n不一样的步幅渐渐接成连贯的轮转。它们越过浅滩与缓坡，在身后留下独特的足迹，也学会在路面变化时重新调整。", hiddenRuleID: "hidden.health.streak.35", series: "健康｜生命与恢复"),
        CollectibleDefinition(id: "hidden.learning.first", name: "启智之灯", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "带着一个问题开始，让理解逐渐亮起来。", details: "小灯的粒核只会照亮眼前的一点，学徒便每天带着一个问题坐到灯下。弄懂一处，他就把新的理解连向曾经看过的事物。\n\n那些微光渐渐接成有方向的灯路。后来，学徒能够用自己的话讲清许多事情，灯体仍留着开放的缺口，等下一个问题走进来。", hiddenRuleID: "hidden.learning.first", series: "学习｜理解与探索"),
        CollectibleDefinition(id: "hidden.learning.streak.7", name: "递进书梯", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "把暂时够不到的地方，拆成可以踏上的一级。", details: "高书架上的星卷遥不可及，小书页便先折出一阶能站稳的梯面。读者在这里弄懂一段文字，再用自己的笔记接起下一阶。\n\n阶梯随着理解逐步延伸，弯曲处也有回看与歇脚的平台。等他抵达星卷所在的地方，脚下每一页都承接着亲自走过的一步。", hiddenRuleID: "hidden.learning.streak.7", series: "学习｜理解与探索"),
        CollectibleDefinition(id: "hidden.learning.streak.14", name: "解谜之钥", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "先理解问题的形状，再选择合适的方法。", details: "小钥匙带着熟练的齿形来到新门前，转了许多次仍打不开。制钥人请它停下来，观察门内的缺口，比较哪些旧方法能够留下，哪些需要重新组合。\n\n钥匙在一次次验证里长出灵活的关节。后来，它遇见陌生的门，总会先认真观察，再试着作出适合眼前问题的调整。", hiddenRuleID: "hidden.learning.streak.14", series: "学习｜理解与探索"),
        CollectibleDefinition(id: "hidden.learning.streak.21", name: "思维星图", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "整理知识之间的联系，也给未知留下位置。", details: "初见星海时，绘图者把每颗星都画得一样大，回头却找不到能够辨认的方向。她选定一个主题，先连起与它关系最近的几颗星。\n\n新的发现逐渐加入，星图有了主线、分支与仍待查证的空白。每次重画，她都能更清楚地说明，自己为何把这些光放在一起。", hiddenRuleID: "hidden.learning.streak.21", series: "学习｜理解与探索"),
        CollectibleDefinition(id: "hidden.learning.streak.28", name: "辨真棱镜", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "追问消息从哪里来，让判断有可核对的依据。", details: "传闻的光穿过集市，到了小棱镜里已经缠成一团。看镜人陪它沿着一束光往回走，找到最初的记录，再比较沿途被加上的颜色。\n\n棱镜慢慢分出了不同的通道。后来，旅人带来新的消息，它会保留尚未确认的部分，也把能够核对的线索清楚映在桌面上。", hiddenRuleID: "hidden.learning.streak.28", series: "学习｜理解与探索"),
        CollectibleDefinition(id: "hidden.learning.streak.35", name: "迁知之桥", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "把熟悉的理解，带到新的场景里验证。", details: "石岸上的学徒懂得搭桥，到了软云的彼岸却无法照搬旧图。他先找出两岸相似的支点，再为不同的地面试做新的连接。\n\n桥身在反复调整中贯通了两种形态。走到另一端时，学徒既带来了熟悉的经验，也学会让经验随着眼前的真实情形继续生长。", hiddenRuleID: "hidden.learning.streak.35", series: "学习｜理解与探索"),
        CollectibleDefinition(id: "hidden.finance.first", name: "聚沙之仓", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "看清每一点积累，让细小的选择有迹可循。", details: "小仓第一次迎来星沙时，地面还松软得留不住重量。看仓人每天清点进出，修好一处缝隙，再把留下的细粒铺成平整的一层。\n\n沙层渐渐稳固，仓中也有了清楚的刻度。走过很久以后，他能从这些记录里看见，许多不起眼的决定如何接成了踏实的积累。", hiddenRuleID: "hidden.finance.first", series: "财务｜积累与选择"),
        CollectibleDefinition(id: "hidden.finance.streak.7", name: "积蓄之树", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "照料已有的基础，再为新的愿望伸出枝条。", details: "幼树急着长出很远的枝叶，却被一阵小风吹得倾斜。园丁陪它检查根部，把有限的水先送到能够稳住树身的地方。\n\n根须在日常照料里伸深，枝干也慢慢有了支撑。后来，新枝向不同方向展开，每一处生长都连着脚下那片被认真照看的土。", hiddenRuleID: "hidden.finance.streak.7", series: "财务｜积累与选择"),
        CollectibleDefinition(id: "hidden.finance.streak.14", name: "分流之渠", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "为不同的需要安排位置，让去向清楚一些。", details: "泉水初到小渠时，所有容器都挤在同一个出口。守渠人逐一写下它们的用途，清开不同的水路，再观察每处实际需要多少。\n\n渠身渐渐分出清晰的方向，新的需求来到，也能重新调整闸口。看着水有条理地流向各处，他终于知道，下一步需要照看的是哪一段。", hiddenRuleID: "hidden.finance.streak.14", series: "财务｜积累与选择"),
        CollectibleDefinition(id: "hidden.finance.streak.21", name: "守储之盾", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "守好重要的储备，也留出合理使用的通道。", details: "小盾把所有缝隙封住以后，仓心的星粒再也送不到需要它们的地方。守仓者陪它辨认哪些门该稳固，哪些门需要有清楚的开合规则。\n\n盾体逐渐形成可靠的环抱，储藏与使用都有了可辨认的路径。新的风浪来到时，守仓者能够检查准备，也知道自己仍有调整的空间。", hiddenRuleID: "hidden.finance.streak.21", series: "财务｜积累与选择"),
        CollectibleDefinition(id: "hidden.finance.streak.28", name: "取舍天平", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "把重要的需要放上桌面，认真作出自己的选择。", details: "旅人把遇见的每件珍物都放上天平，直到两端沉得无法移动。看秤人请他逐件说明，这件东西会用在哪里，又要为它留下多少空间。\n\n支点随着清楚的回答慢慢调整。后来，旅人仍会遇见心动的珍物，却能够比较眼前的需要与更长的打算，作出自己愿意承担的取舍。", hiddenRuleID: "hidden.finance.streak.28", series: "财务｜积累与选择"),
        CollectibleDefinition(id: "hidden.finance.streak.35", name: "远期灯塔", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "让长远的愿望，也有今天可以照料的一层。", details: "小塔望着遥远的海面，总觉得自己的灯太低。筑塔人先标出想照见的航道，再把需要的材料与工作分成能够逐日完成的几层。\n\n塔身在不断检查中接续，灯光终于越过近岸。此后，每当航道与天气变化，筑塔人都会重新查看目标，让灯继续指向真正想抵达的地方。", hiddenRuleID: "hidden.finance.streak.35", series: "财务｜积累与选择"),
        CollectibleDefinition(id: "hidden.relationships.first", name: "共鸣双铃", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "认真听见彼此，再用自己的方式回应。", details: "两枚小铃起初总想发出一样的声音，越用力模仿，回声越混乱。挂铃人把它们稍稍分开，留出能听清另一枚铃声的距离。\n\n它们渐渐辨认出不同的音色，在停顿里接住彼此的回应。风再次经过时，两种声音交织在一起，各自清楚，也比独自响起时更加丰富。", hiddenRuleID: "hidden.relationships.first", series: "关系｜连接与回应"),
        CollectibleDefinition(id: "hidden.relationships.streak.7", name: "交织之根", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "相互支持的时候，也照顾各自伸展的空间。", details: "两株幼树想靠得更近，根须却在紧紧缠绕中挤住了新的嫩芽。护林人陪它们松开过密的地方，让水分能够往来，也让各自有能扎根的土。\n\n随着季节更替，根系在适当的位置承接重量。风起时，它们能彼此照应；新芽醒来时，也都有自己的方向可以继续生长。", hiddenRuleID: "hidden.relationships.streak.7", series: "关系｜连接与回应"),
        CollectibleDefinition(id: "hidden.relationships.streak.14", name: "相向之桥", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "把自己的那一段做好，也留意对方的回应。", details: "两岸的人都盼着桥能到达自己脚下，却一直隔水等待。后来，他们约好一个能看见彼此的清晨，各自从岸边搭起第一段。\n\n桥身在交流与调整中相向延伸，遇见偏差便一起修正。接合那天，两岸的人走到中间，亲手试过承重，再把来往的路慢慢铺好。", hiddenRuleID: "hidden.relationships.streak.14", series: "关系｜连接与回应"),
        CollectibleDefinition(id: "hidden.relationships.streak.21", name: "倾听之螺", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "先给对方完整说出的空间，再慢慢确认理解。", details: "小海螺总在话音落下以前送回自己的回声，来客渐渐不再开口。守螺人替它清出一道空腔，请它先把听见的话留一会儿。\n\n海螺学会容纳停顿，也学会用温和的回声确认来意。后来，许多不同的声音从两端进入，在这里找到被认真接住的位置。", hiddenRuleID: "hidden.relationships.streak.21", series: "关系｜连接与回应"),
        CollectibleDefinition(id: "hidden.relationships.streak.28", name: "边界之庭", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "把愿意与不愿意说清楚，让相处有安心的地方。", details: "小庭院为了迎接所有来客，拆掉了每一道围栏，花床很快被踩乱。园丁陪它重新留好入口、步道与休息的间隔，再把约定写在门旁。\n\n庭院渐渐长成温暖的环抱。来客知道怎样走近，主人也能够安心表达需要。大家沿着清楚的路往来，花与树都有了继续生长的空间。", hiddenRuleID: "hidden.relationships.streak.28", series: "关系｜连接与回应"),
        CollectibleDefinition(id: "hidden.relationships.streak.35", name: "同行双帆", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "商量共同的方向，也容许彼此采用不同的姿态。", details: "两面帆总以同一个角度迎风，小舟却不断在原地打转。掌舵人请它们先确认要去的海岸，再分别调整受风的位置。\n\n双帆渐渐学会在变化里配合，有时一面先收，有时另一面展开。它们始终保持交流，让不同的角度，也能共同支持一段想走下去的航程。", hiddenRuleID: "hidden.relationships.streak.35", series: "关系｜连接与回应"),
        CollectibleDefinition(id: "hidden.career.first", name: "筑梦之锤", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "把想法落在一件能够完成的作品上。", details: "小锤在工坊里画出许多宏大的轮廓，却总在落下时散开。工匠先陪它接稳柄与锤首，选一块合适的材料，试着敲出第一个能够使用的构件。\n\n一次次检查与修正之后，构件接成了真实的作品。小锤仍会想象更远的形状，也知道如何把愿望交给双手，逐步变成别人能够看见的东西。", hiddenRuleID: "hidden.career.first", series: "事业｜创造与担当"),
        CollectibleDefinition(id: "hidden.career.streak.7", name: "承重之柱", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "确认自己承接的责任，也建立可靠的支持。", details: "云屋扩建时，小柱独自接下每一处重量，渐渐弯得无法继续。筑屋者把需要承接的部分逐一标清，添上相互支援的支点，再一起试过连接。\n\n主轴在清楚的分工中站稳。后来，云屋迎来更多来客，每次增加新的空间，大家都会先确认支撑是否准备妥当。", hiddenRuleID: "hidden.career.streak.7", series: "事业｜创造与担当"),
        CollectibleDefinition(id: "hidden.career.streak.14", name: "开拓之钻", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "先找准一个值得验证的方向，再把力量集中起来。", details: "小钻在石壁前不断换方向，留下许多浅浅的痕迹。探路人请它选出最有依据的一处，记录阻力与变化，再用一段完整的时间认真试探。\n\n粒流渐渐汇向清晰的前端，第一条通道终于透进风来。它记下这次验证的结果，也为下一处未知，留下能够继续检查的线索。", hiddenRuleID: "hidden.career.streak.14", series: "事业｜创造与担当"),
        CollectibleDefinition(id: "hidden.career.streak.21", name: "协作齿轮", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "把交接说清楚，让每一份工作都能接得上。", details: "工坊里的轮体各自转得很快，拼到一起却频频卡住。修轮人请大家慢下来，标明各自送出的东西，以及接手时真正需要的形状。\n\n接口在一次次交流中逐渐贴合。后来，工坊能够平稳地运转，遇见新的构件，大家也会留出调整的余地，让合作沿着清楚的衔接继续。", hiddenRuleID: "hidden.career.streak.21", series: "事业｜创造与担当"),
        CollectibleDefinition(id: "hidden.career.streak.28", name: "应变枢纽", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "情况变化时，重新确认重点与能够调动的力量。", details: "风暴改变了云港的航道，小枢纽仍照着旧图分配支臂，忙碌中不断失衡。守港人陪它查看新的路况，暂停不再需要的线路，再把力量送向最紧要的地方。\n\n核心逐渐稳定下来，支臂也有了灵活的连接。此后，每当环境变化，它都会先确认眼前的真实情形，再组织下一轮行动。", hiddenRuleID: "hidden.career.streak.28", series: "事业｜创造与担当"),
        CollectibleDefinition(id: "hidden.career.streak.35", name: "交付之印", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "把最后的细节核对清楚，让成果能够真正交到别人手中。", details: "小印器的纹样已经成形，却总差几处细小的接缝。制印人摊开最初的约定，逐项检查用途、边缘与承接的位置，请真正使用它的人也来试一试。\n\n零散的构件终于各归其位，印记清楚落在纸上。交接那天，制印人把使用方法一同递出，让完成的作品，能够安稳进入接下来的日常。", hiddenRuleID: "hidden.career.streak.35", series: "事业｜创造与担当"),
        CollectibleDefinition(id: "hidden.interests.first", name: "随想之弦", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "给自己的好奇一点时间，听它慢慢形成声音。", details: "小弦总想奏出传说里的旋律，却发现自己的长短与旧琴谱不同。旅乐人请它先试一试眼前的声音，记下喜欢的节奏，再自由连接其中的片段。\n\n弦与弦之间逐渐有了独特的回响。路过的人停下来听见一段从未听过的曲子，而小弦终于愿意继续探索，属于自己的下一种声音。", hiddenRuleID: "hidden.interests.first", series: "兴趣｜好奇与表达"),
        CollectibleDefinition(id: "hidden.interests.streak.7", name: "幻形之笔", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "让脑海里的画面，先有一次落在纸上的机会。", details: "小笔藏着许多会变形的念头，总怕纸上的轮廓不够漂亮。画师递来一叠练习纸，请它每天挑一个有趣的画面，用最顺手的方式留下。\n\n笔锋在尝试里学会散开与重聚，原先模糊的想象也逐渐显出细节。后来，它拥有了一本不太整齐却十分鲜活的画册，每一页都能引出新的念头。", hiddenRuleID: "hidden.interests.streak.7", series: "兴趣｜好奇与表达"),
        CollectibleDefinition(id: "hidden.interests.streak.14", name: "拾趣万花筒", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "留意日常的小发现，让好奇拥有可以重组的材料。", details: "小筒原本只有几片平常的碎光，旅人便在路上收集一片叶影、一段窗纹和水面的折光。每添一片，他们都停下来转一转，看看会出现什么。\n\n熟悉的碎片渐渐拼出出人意料的空间。万花筒仍陪旅人走在普通的街巷，让那些被认真注意过的小事，继续成为想象的起点。", hiddenRuleID: "hidden.interests.streak.14", series: "兴趣｜好奇与表达"),
        CollectibleDefinition(id: "hidden.interests.streak.21", name: "即兴舞环", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "在熟悉的基础上试一点变化，找到表达的乐趣。", details: "小舞环背熟了每一个转弯，一旦乐声改变就僵在半空。舞者陪它保留最舒服的起步，再给下一次旋转留出一点自由选择的空间。\n\n经过许多轻松的尝试，环体能够随着不同的乐声舒展。它仍记得回到熟悉的落点，也越来越愿意在途中回应一段新的节奏。", hiddenRuleID: "hidden.interests.streak.21", series: "兴趣｜好奇与表达"),
        CollectibleDefinition(id: "hidden.interests.streak.28", name: "寻奇之镜", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "多看一眼平常的事物，也许就会遇见新的问题。", details: "小镜每天面对同一片石墙，觉得自己再也找不到新东西。磨镜人请它靠近一点，换一个光线，再沿着石纹缓慢移动。\n\n细小的结晶与藏在缝中的嫩芽逐渐显现。后来，小镜陪旅人观察许多熟悉的地方，让平常的事物，也能打开一段值得继续探寻的旅程。", hiddenRuleID: "hidden.interests.streak.28", series: "兴趣｜好奇与表达"),
        CollectibleDefinition(id: "hidden.interests.streak.35", name: "造梦工坊", kind: .hidden, ordinaryIndex: nil,
            symbolName: "sparkles", silhouetteSymbolName: "questionmark",
            summary: "把喜欢的碎片拿来试做，让想象拥有实际的形状。", details: "小工坊堆满旅人舍不得丢的碎片，门前却一直没有新的作品。一天，他们挑出几件彼此合适的材料，约好先做一件能够转起来的小装置。\n\n装置在修改与试玩中逐渐成形，也带来了下一次组合的灵感。工坊从此留出一张工作台，让每个有趣的念头，都能在这里获得一次亲手尝试的机会。", hiddenRuleID: "hidden.interests.streak.35", series: "兴趣｜好奇与表达")
    ]
}
